create table password_challenges(id uuid primary key,user_id bigint not null references users(id),token_hash varchar(64) not null unique,otp_hash varchar(255) not null,expires_at timestamptz not null,attempts integer not null default 0 check(attempts between 0 and 5),used_at timestamptz,created_at timestamptz not null default current_timestamp);
create index password_challenge_user_idx on password_challenges(user_id,created_at desc);
create table mail_outbox(id bigint generated by default as identity primary key,recipient varchar(100) not null,subject varchar(200) not null,body text not null,status varchar(20) not null default 'PENDING' check(status in ('PENDING','SENDING','SENT','FAILED')),attempts integer not null default 0,available_at timestamptz not null default current_timestamp,created_at timestamptz not null default current_timestamp,sent_at timestamptz);
create index mail_pending_idx on mail_outbox(available_at,id) where status in ('PENDING','SENDING');
